\begin{theorem}[Peano Iterator Theorem]
\label{thm:peano-iterator-theorem}
Let $(P,S,1)$ be a Peano system, and let $(W,c,g)$ be iterator data for it.
Then there exists a unique function $f:P\to W$ such that
\[
f(1)=c
\qquad\text{and}\qquad
\forall n\in P\;(f(S(n))=g(f(n))).
\]
\hyperref[prf:peano-iterator-theorem]{Go to proof.}
\end{theorem}
\end{theorembox}

\begin{formalizationrecord}{Lean 4 Verification Record}
\FormalizationSource{Feferman, \emph{The Number Systems}, Theorem 3.4; Mendelson, \emph{Number Systems and the Foundations of Analysis}, Section 2.2}
\Formalizes{thm:peano-iterator-theorem}
\textbf{Lean module:} \texttt{LRA.VolumeII.PeanoSystems.Recursion}.\par
\LeanDeclaration{peano\_iterator\_theorem}
\textbf{Status:} checked against \texttt{lra-lean}.\par

\begin{leancode}
theorem peano_iterator_theorem
    (ps : PeanoSystem)
    (target : Type)
    (initial_value : target)
    (step_rule : target -> target) :
    Exists (fun iterator_function : ps.carrier -> target =>
      And
        (satisfies_iterator_clauses
          ps target initial_value step_rule iterator_function)
        (forall other_iterator : ps.carrier -> target,
          satisfies_iterator_clauses
            ps target initial_value step_rule other_iterator ->
          forall element : ps.carrier,
            other_iterator element = iterator_function element)) := by
  refine
    Exists.intro
      (iter ps target initial_value step_rule)
      ?_
  constructor
  exact iter_satisfies_iterator_clauses ps target initial_value step_rule
  intro other_iterator other_satisfies element
  exact
    Eq.symm
      (iterator_function_unique
        ps target initial_value step_rule
        (iter ps target initial_value step_rule)
        other_iterator
        (iter_satisfies_iterator_clauses ps target initial_value step_rule)
        other_satisfies
        element)
\end{leancode}
\end{formalizationrecord}

\begin{remark*}[Standard quantified statement]
\[
\exists! f:P\to W\;
\bigl(f(1)=c\land \forall n\in P\;(f(S(n))=g(f(n)))\bigr).
\]
\end{remark*}

\begin{remark*}[Predicate reading]
\[
\exists! f:P\to W\;
\operatorname{IteratorFunction}(f,(P,S,1),W,c,g).
\]
\end{remark*}

\begin{remark*}[Negated quantified statement]
\[
\begin{aligned}
&\neg\exists! f:P\to W\;
\bigl(f(1)=c\land \forall n\in P\;(f(S(n))=g(f(n)))\bigr).
\end{aligned}
\]
\end{remark*}

\begin{remark*}[Failure modes]
\begin{description}
  \item[Exposition.]
  The iterator theorem fails only if no function satisfies the iterator
  clauses or if more than one function satisfies them.
  \item[Existence or uniqueness failure.]
  \[
  \neg\exists! f:P\to W\;
  \operatorname{IteratorFunction}(f,(P,S,1),W,c,g).
  \]
  \[
  \begin{aligned}
  &\neg\exists! f:P\to W\;
  \bigl(f(1)=c\land \forall n\in P\;(f(S(n))=g(f(n)))\bigr)\\
  \Longleftrightarrow\;&
  \underbrace{\neg\exists f:P\to W\;
  \bigl(f(1)=c\land \forall n\in P\;(f(S(n))=g(f(n)))\bigr)}_{\text{existence fails}}\\
  &\lor
  \underbrace{\exists f,h:P\to W\;
  \bigl(f\neq h\land f(1)=c\land h(1)=c
  \land \forall n\in P\;(f(S(n))=g(f(n)))
  \land \forall n\in P\;(h(S(n))=g(h(n)))\bigr)}_{\text{uniqueness fails}}.
  \end{aligned}
  \]
\end{description}
\end{remark*}

\begin{remark*}[Interpretation]
The theorem says that iterator data is sufficient to turn a recursive
specification into a genuine definition: there is exactly one graph and hence
exactly one function satisfying the base and successor clauses.
\end{remark*}

\begin{remark*}[Historical note]
This is the one-based Peano-system version of the iterator theorem in
\citet{FefermanNumberSystems1964,MendelsonNumberSystemsFoundationsAnalysis,simpson2011peanosystems}.
It is also the set-theoretic instance of the natural numbers object universal
property \citep{lawvere1969adjointness}; Dedekind's recursion theorem is the
classical ancestor \citep{dedekind1901essays}.
\end{remark*}

